C = (0, 3.5);
D = (1.7, 2.3);
E = (0, 2.3);
F = (.85, .95);
G = (2.2, 0);
H = (-.85, 2.1);
K = (3.3, -.75);
L = (0, .8);
draw(A--B--C--A);
draw(D--E);
