\end{align*}
(The  $E$  and  $1/E$  term cancel with each other)
\begin{align*}
&\iff 2x^4y^6z+2x^4y^5z^2+2x^4y^2z^5+2x^4yz^6+4x^4y^4z^3+4x^4y^3z^4+2x^3y^6z^2+2x^3y^2z^6+4x^3y^4z^4+x^9y^2+x^9z^2+x^7y^4+x^7z^4+2x^7y^2z^2+x^3y^6z^2+2x^3y^4z^4+x^3y^2z^6&-xy^6z^4-xy^4z^6+x^8(x^3+y^2z+yz^2+z^3)+x^6(y^5+y^4z+2y^3z^2+2y^2z^3+yz^4+z^5)+x^2(y^2z^7+y^3z^6+2y^4z^5+2y^5z^4+y^6z^3+y^7z^2)-y^2z^4-y^6z^5-y^5z^6-y^4z^7
