pair A=dir(115);
pair B=dir(220);
pair C=dir(-40);
pair H=orthocenter(A,B,C);
pair G=0.27*A+0.35*B+0.38*C;
pair G2=2*foot(G,A,C)-G;
pair G3=2*foot(G,A,B)-G;
pair H3=2*foot(H,A,B)-H;
pair H2=2*foot(H,A,C)-H;
pair P=extension(G3,H3,G2,H2);

draw(circumcircle(A,B,C));
draw(A--B--C--cycle);
draw(circumcircle(A,G2,G3));
draw(H--G);
draw(G3--P);
draw(H2--P);
draw(H--H2,dotted);
draw(H--H3,dotted);
draw(G--G2,dotted);
draw(G--G3,dotted);

dot(" $A$ ",A,dir(135));
dot(" $B$ ",B,dir(B));
dot(" $C$ ",C,dir(C));
dot(" $H$ ",H,dir(-90));
dot(" $G$ ",G,dir(-90));
dot(" $G_2$ ",G2,dir(-20));
dot(" $G_3$ ",G3,dir(G3));
