&= \frac{a^2c\left(\frac{a+b+c}{b} - \frac{b}{a} - 1 - \frac{b}{c} \right)}{c^2 - a^2}
&= \frac{a^2bc \left( \frac{a+b+c}{b} - \frac{b(a+c)}{ac} - 1 \right)}{b(c^2 - a^2)}
