0 & 0 & 1
-\frac{1}{b} & \frac{c}{a-c} & a-c
-\frac{1}{c} & \frac{b}{a-b} & a-b
\end{vmatrix} \div \begin{vmatrix}
0 & 0 & 1
-\frac{1}{b} & 1 & a - c
-\frac{1}{c} & 1 & a - b
\end{vmatrix}
